#include <bits/stdc++.h>

using namespace std;

using ll = long long;
using i128 = __int128_t;

const int MOD = 998244353;

string to_string(i128 x) {
    if (x == 0) return "0";
    string s;
    bool neg = x < 0;
    if (neg) x = -x;
    while (x > 0) {
        s += '0' + (x % 10);
        x /= 10;
    }
    if (neg) s += '-';
    reverse(s.begin(), s.end());
    return s;
}

void solve_with_sum(const vector<int>& coeffs, int base, i128& result) {
    int n = coeffs.size();
    vector<int> left_part, right_part;

    function<void(int, int)> left_dfs = [&](int idx, int cur) {
        if (idx == n / 2) {
            left_part.push_back((cur + base) % MOD);
            return;
        }
        left_dfs(idx + 1, cur);
        left_dfs(idx + 1, (cur + coeffs[idx]) % MOD);
    };

    left_dfs(0, 0);

    function<void(int, int)> right_dfs = [&](int idx, int cur) {
        if (idx == n) {
            right_part.push_back(cur);
            return;
        }
        right_dfs(idx + 1, cur);
        right_dfs(idx + 1, (cur + coeffs[idx]) % MOD);
    };

    right_dfs(n / 2, 0);

    sort(left_part.begin(), left_part.end());
    sort(right_part.begin(), right_part.end());

    ll sum_right = 0;
    for (int x : right_part) sum_right = (sum_right + x) % MOD;

    int j = right_part.size() - 1;
    for (int x : left_part) {
        while (j >= 0 && x + right_part[j] >= MOD) --j;
        result += (ll)x * right_part.size() + sum_right - (ll)(right_part.size() - 1 - j) * MOD;
    }
}

ll power10[17];

ll count_prefix_numbers(const string& prefix, ll max_val, const string& n_str) {
    ll val = 0;
    for (char c : prefix) val = val * 10 + (c - '0');

    ll count = 0;
    int plen = prefix.length();
    int nlen = n_str.length();

    for (int len = plen; len <= nlen; ++len) {
        if (len < nlen) {
            count += power10[len - plen];
        } else {
            if (prefix < n_str) {
                count += power10[len - plen];
            } else if (prefix == n_str) {
                count += max_val - val * power10[nlen - plen] + 1;
            }
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    ll n;
    cin >> n;

    string ns;
    if (n == 0) ns = "0";
    else {
        ll t = n;
        while (t) {
            ns += '0' + (t % 10);
            t /= 10;
        }
        reverse(ns.begin(), ns.end());
    }

    power10[0] = 1;
    for (int i = 1; i < 17; ++i) power10[i] = power10[i-1] * 10;

    i128 answer = 0;

    for (int length = 1; length <= (int)ns.size(); ++length) {
        for (int diff_index = 0; diff_index < min(length, (int)ns.size()); ++diff_index) {
            string current;
            ll value = 0;

            for (int i = 0; i < diff_index; ++i) {
                current += ns[i];
                value = value * 10 + (ns[i] - '0');
            }

            for (int digit = 0; digit <= 9; ++digit) {
                if (diff_index == 0 && digit == 0) continue;
                if (diff_index < (int)ns.size() && digit == ns[diff_index] - '0') continue;
                if (length == (int)ns.size() && digit > ns[diff_index] - '0') continue;

                string new_current = current + char('0' + digit);
                ll new_value = value * 10 + digit;

                ll base = 0;
                string temp;

                for (int i = 0; i < (int)new_current.size(); ++i) {
                    char start_char = (i == 0) ? '1' : '0';
                    for (char c = start_char; c < new_current[i]; ++c) {
                        base += count_prefix_numbers(temp + c, n, ns);
                    }
                    temp += new_current[i];
                }
                base += (int)new_current.size() - 1;

                vector<int> variables;
                temp = new_current;
                for (int i = new_current.size(); i < length; ++i) {
                    int cnt = count_prefix_numbers(temp + '0', n, ns) % MOD;
                    variables.push_back(cnt);
                    temp += '0';
                }

                base += 1;
                base -= new_value * power10[length - new_current.size()];

                for (int i = 0; i < (int)variables.size(); ++i) {
                    variables[(int)variables.size() - 1 - i] -= power10[i] % MOD;
                }

                int b = base % MOD;
                if (b < 0) b += MOD;

                for (int& v : variables) {
                    v %= MOD;
                    if (v < 0) v += MOD;
                }

                solve_with_sum(variables, b, answer);
            }
        }
    }

    // Handle exact prefixes
    string prefix;
    ll val = 0;
    for (int len = 1; len <= (int)ns.size(); ++len) {
        prefix += ns[len-1];
        val = val * 10 + (ns[len-1] - '0');

        ll cnt = 1;
        string temp;
        for (int i = 0; i < (int)prefix.size(); ++i) {
            char start_char = (i == 0) ? '1' : '0';
            for (char c = start_char; c < prefix[i]; ++c) {
                cnt += count_prefix_numbers(temp + c, n, ns);
            }
            temp += prefix[i];
        }
        cnt += (int)prefix.size() - 1;
        cnt -= val;
        cnt %= MOD;
        if (cnt < 0) cnt += MOD;

        answer += cnt;
    }

    answer %= 1000000007LL;
    cout << to_string(answer) << "\n";

    return 0;
}
